import { IMAGE_MANIFEST } from "./image-manifest";

/**
 * Right-sized, locally served WebP (and AVIF for heroes) variants for Lovable
 * remote image assets. Variants are generated by scripts/optimize-images.py into
 * /public/img. Unknown URLs fall back to the original asset untouched.
 */
export type ResponsiveImage = {
  src: string;
  srcSet?: string;
  avifSrcSet?: string;
  width?: number;
  height?: number;
};

export function responsiveImage(url: string, maxWidth?: number): ResponsiveImage {
  const v = IMAGE_MANIFEST[url];
  if (!v) return { src: url };
  const widths = maxWidth ? v.widths.filter((w, i) => w <= maxWidth || i === 0) : v.widths;
  const set = (ext: string) => widths.map((w) => `/img/${v.stem}-${w}.${ext} ${w}w`).join(", ");
  const fallback = widths[Math.min(1, widths.length - 1)];
  return {
    src: `/img/${v.stem}-${fallback}.webp`,
    srcSet: set("webp"),
    avifSrcSet: v.avif ? set("avif") : undefined,
    width: v.w,
    height: v.h,
  };
}

/** Smallest variant at least `minWidth` px wide (for single-URL slots like video posters). */
export function imageAtLeast(url: string, minWidth: number): string {
  const v = IMAGE_MANIFEST[url];
  if (!v) return url;
  const w = v.widths.find((x) => x >= minWidth) ?? v.widths[v.widths.length - 1];
  return `/img/${v.stem}-${w}.webp`;
}
